(function() {
  'use strict';
    var SPACE_EXPORT = 'spaceExportQRCode';
    var record = new Array();

    kintone.events.on(['app.record.detail.show', 'mobile.app.record.detail.show'], function(event) {
        record = event.record;
        var SPACE_EXPORT = 'spaceExportQRCode';
        var html = '';
            html += '<style>';
            html += '   .button { background-color: #85C1E9; border: none; color: white; padding: 2px 10px; text-align: center; text-decoration: none; display: inline-block; font-size: 10pt; -webkit-transition-duration: 0.4s; transition-duration: 0.4s; cursor: pointer; border-radius: 8px; box-shadow: 0 3px #666666 }';
            html += '   .button1 { background-color: #DCE1E8; color: #666666; border: 2px solid #666666; }';
            html += '   .button1:hover { background-color: #85C1E9; color: white; border: 2px solid #2874A6; box-shadow: 0 3px #2874A6 }';
            // html += '   .button1:focus { background-color: #85C1E9; color: white; border: 2px solid #2874A6; box-shadow: 0 3px #2874A6 }';
            html += '   .button1:active { background-color: #4384AF; color: white; border: 2px solid #12517A; box-shadow: 0 3px #12517A; transform: translateY(4px); }';
            html += '</style>';
            html += '<table border="0" cellspacing="0" cellpadding="0">';
            // html += '   <tr style="line-height: 50px" border="1">';
            html += '   <tr>';
            html += '       <td align="left" width="7px"></td>';
            html += '       <td align="left" width="250px">';
            html += '           <button class="button button1" type="button" id="my_button">Print Excel QRCode</button>';
            html += '       </td>';
            html += '   </tr>';
            html += '</table>';

        // kintone.app.record.getHeaderMenuSpaceElement().innerHTML = html;
        kintone.app.record.getSpaceElement(SPACE_EXPORT).innerHTML = html;

        document.getElementById("my_button").addEventListener("click", function() {
            // showSpinner();
            createFormattingWorkbook(record);
            // hideSpinner(); // Hide the spinner
        });

        return event;
    });
    
    var headerFontSize = 12 * 20;
    var headerBackgroundColor = '#A6A6A6';
    var detailFontSize = 5 * 20;
    var detailBackgroundColor = '#FFFF00';

    function cellBorders(cell){
        cell.cellFormat().leftBorderColorInfo(new $.ig.excel.WorkbookColorInfo('#000000'));
        cell.cellFormat().rightBorderColorInfo(new $.ig.excel.WorkbookColorInfo('#000000'));
        cell.cellFormat().topBorderColorInfo(new $.ig.excel.WorkbookColorInfo('#000000'));
        cell.cellFormat().bottomBorderColorInfo(new $.ig.excel.WorkbookColorInfo('#000000'));
    }

    function cellHeaderFormat(cell){
        cell.cellFormat().alignment($.ig.excel.HorizontalCellAlignment.center);
        cell.cellFormat().verticalAlignment($.ig.excel.VerticalCellAlignment.center);
        cell.cellFormat().fill($.ig.excel.CellFill.createSolidFill(headerBackgroundColor));
        cell.cellFormat().font().colorInfo(new $.ig.excel.WorkbookColorInfo($.ig.excel.WorkbookThemeColorType.light1));
        cell.cellFormat().font().height(headerFontSize);
        cell.cellFormat().font().name('Arial');
        cell.cellFormat().font().bold(true);
    }

    function cellDetailFormat(cell){
        cell.cellFormat().alignment($.ig.excel.HorizontalCellAlignment.left);
        cell.cellFormat().verticalAlignment($.ig.excel.VerticalCellAlignment.center);
        cell.cellFormat().font().height(detailFontSize);
        cell.cellFormat().font().name('Leelawadee');
        cell.cellFormat().font().bold(true);
    }
    
    function cellDetailFormat2(cell){
        cell.cellFormat().alignment($.ig.excel.HorizontalCellAlignment.left);
        cell.cellFormat().verticalAlignment($.ig.excel.VerticalCellAlignment.top);
        cell.cellFormat().font().height(detailFontSize);
        cell.cellFormat().font().name('Leelawadee');
        cell.cellFormat().font().bold(true);
    }
	
	function setBorders(sheet){
		for(var j = 0; j < 26; j++){
        sheet.rows(0).cells(j).cellFormat().topBorderColorInfo(new $.ig.excel.WorkbookColorInfo('#000000'));
        sheet.rows(11).cells(j).cellFormat().bottomBorderColorInfo(new $.ig.excel.WorkbookColorInfo('#000000'));
			if(j < 12){
				sheet.rows(j).cells(0).cellFormat().leftBorderColorInfo(new $.ig.excel.WorkbookColorInfo('#000000'));
			  sheet.rows(j).cells(25).cellFormat().rightBorderColorInfo(new $.ig.excel.WorkbookColorInfo('#000000'));
			}
    }
	}
    
    function createFormattingWorkbook(record){
		var recordData = record;
        
    var workbook = new $.ig.excel.Workbook($.ig.excel.WorkbookFormat.excel2007);
		
		// ID field in table
//		var NO = 'Text';
//		var BRANCH = 'Drop_down_0';
//		var DEPARTMENT = 'Drop_down_1';
//		var TYPE = 'Drop_down';
//		var NAME = 'Text_0';
//		var PERSON_NAME = 'Text_3';
//		var FIXED_ASSET_NO = 'Text';
		
		
		//NEW  
		var Id = 'Number';
		var Name = 'Text';
		var Section = 'Drop_down';
		
//		var DEVICE_TYPE = 'Drop_down';
//		var ASSET_NO = 'Text';
//		var PIC = 'Text_4';
//		var LOCATION = 'Drop_down_4';
//		var NAME    = 'Text_0';
//		var TYPE    = 'Drop_down_3';
		
		
		// Data in field
 //       var field_NO = recordData[NO].value;
  //      var field_BRANCH = recordData[BRANCH].value;
//        var field_DEPARTMENT = recordData[DEPARTMENT].value;
 //       var field_TYPE = recordData[TYPE].value;
//        var field_NAME = recordData[NAME].value;  
 //       var field_PERSON_NAME = recordData[PERSON_NAME].value;
//        var field_FIXED_ASSET_NO = recordData[FIXED_ASSET_NO].value;
        
        
     //NEW   
        var field_ID = recordData[Id].value;
        var field_Name =recordData[Name].value;
        var field_Section = recordData[Section].value;
      
 //       var field_DEVICE_TYPE = recordData[DEVICE_TYPE].value;
 //       var field_ASSET_NO = recordData[ASSET_NO].value;
 //       var field_PIC = recordData[PIC].value;
 //       var field_LOCATION = recordData[LOCATION].value;
 //       var field_NAME = recordData[NAME].value;
 //       var field_TYPE = recordData[TYPE].value;
        
		
		
		
		// Sheet Name
        var sheet_name = 'Employee ID' + ' ' + field_ID;
        var sheet = workbook.worksheets().add(sheet_name);
		
		// Specify row in for loop
        var row1 = 0;
        var row2 = 1;
        var row3 = 2;
        var row4 = 3;
        var row5 = 4;
        var row6 = 5;
        var row7 = 6;
        var row8 = 7;
        var row9 = 8;
        var row10 = 9;
        var row11 = 10;
		
		// adjust columns width
		sheet.columns(0).width(7 * 20);
		sheet.columns(25).width(7 * 20);
    for(var j = 1; j < 25; j++){
        sheet.columns(j).width(14 * 20);
    }
		
		// adjust row height
		sheet.rows(0).height(3 * 20);
		sheet.rows(11).height(3 * 20);
		for(var j = 1; j < 11; j++){
			sheet.rows(j).height(6.75 * 20);
    }
		
		 // Collect data QR code base64
        var arrayQRCode = new Array();
		    var qrcode_base64 = Create_QRCode(recordData);
        arrayQRCode.push(qrcode_base64);
        console.log('qrcode_base64 : ' + JSON.stringify(qrcode_base64));
        
        // Delete Image QR Code
        document.getElementById("user-js-space").innerHTML = "";
		
		
		//var mergedCell_B1E4 = sheet.mergedCellsRegions().add(row2, 1, row6, 5);
		var mergedCell_H1M1 = sheet.mergedCellsRegions().add(row2, 10, row2, 24);
		var mergedCell_H2M2 = sheet.mergedCellsRegions().add(row3, 10, row3, 24);
		var mergedCell_H3M3 = sheet.mergedCellsRegions().add(row4, 10, row4, 24);
		var mergedCell_H4M4 = sheet.mergedCellsRegions().add(row5, 10, row5, 24);
		var mergedCell_H5M5 = sheet.mergedCellsRegions().add(row6, 10, row10, 24);
		var mergedCell_H6M6 = sheet.mergedCellsRegions().add(row11, 10, row11, 24);
		setBorders(sheet);
		
		// Set image QR Code
		var topLeft = 'B2';
		var bottomRight = 'J10';
		var image = arrayQRCode[0];
		var imageShape = new $.ig.excel.WorksheetImage(image);
		imageShape.topLeftCornerCell(sheet.getCell(topLeft));
		imageShape.bottomRightCornerCell(sheet.getCell(bottomRight));
		sheet.shapes().add(imageShape);
        //cellBorders(mergedCell_B1E4);
		

		
		/*
		mergedCell_H1M1.value('สาขา : ' + field_BRANCH);
		mergedCell_H1M1.cellFormat().shrinkToFit(true);
		cellDetailFormat(mergedCell_H1M1);
		
		mergedCell_H2M2.value('แผนก : ' + field_DEPARTMENT);
		mergedCell_H2M2.cellFormat().shrinkToFit(true);
		cellDetailFormat(mergedCell_H2M2);
		
		mergedCell_H3M3.value('ประเภท : ' + field_TYPE);
		mergedCell_H3M3.cellFormat().shrinkToFit(true);
		cellDetailFormat(mergedCell_H3M3);
		
		
		*/
	
	  //new	replace
		mergedCell_H1M1.value('Name : ' +field_Name);
		mergedCell_H1M1.cellFormat().shrinkToFit(true);
		cellDetailFormat(mergedCell_H1M1);
		
		
		mergedCell_H2M2.value('Section: ' + field_Section );
		mergedCell_H2M2.cellFormat().shrinkToFit(true);
		cellDetailFormat(mergedCell_H2M2);

/*
  	mergedCell_H3M3.value('PIC : ' + field_PIC );
		mergedCell_H3M3.cellFormat().shrinkToFit(true);
		cellDetailFormat(mergedCell_H3M3);
		

		mergedCell_H4M4.value('LOCATION : ' + field_LOCATION );
		mergedCell_H4M4.cellFormat().shrinkToFit(true);
		cellDetailFormat(mergedCell_H4M4);
		
		mergedCell_H5M5.value('NAME : ' + field_NAME);
		mergedCell_H5M5.cellFormat().shrinkToFit(true);
		mergedCell_H5M5.cellFormat().wrapText(true);
		cellDetailFormat2(mergedCell_H5M5);
		
		mergedCell_H6M6.value('TYPE : ' +field_TYPE);
		mergedCell_H6M6.cellFormat().shrinkToFit(true);
		cellDetailFormat(mergedCell_H6M6);
		
	*/	
		
		// Name excel file
        // var file_name = 'Excel_QRCode_' + date.getFullYear() + month + date.getDate() + date.getHours() + date.getMinutes() + date.getSeconds() + '.xlsx';
        var file_name = 'Emp_id_' + field_ID + '.xlsx';

        // Set print preview
        sheet.printOptions().scalingType(1);
        sheet.printOptions().maxPagesHorizontally(1);
        sheet.printOptions().maxPagesVertically(0);
        sheet.printOptions().paperSize(9);

        // Save the workbook
        saveWorkbook(workbook, file_name);
    }
	
	function saveWorkbook(workbook, name) {
		workbook.save({ type: 'blob' }, function (data) {
			saveAs(data, name);
		}, function (error) {
			alert('Error exporting: : ' + error);
		});
    }

    
    function Create_QRCode(record){
      console.log(JSON.stringify(record));
        var recordData = record;

        var Record_number = record["Record_number"]["value"];
        var name = record["Text"]["value"];
        var section = record["Drop_down"]["value"];
      //  var qrshow = "https://ttmet.cybozu.com/k/211/show#record=" + Record_number;
        var qrshow =   name +"/" + section ;
      //    var qrshow =   name;
        $('#user-js-space').qrcode({text: qrshow});

        var spaceDiv = document.getElementById('user-js-space');
        var canvas = spaceDiv.children[0];
        var dataURL = canvas.toDataURL();
        var bin = window.atob(dataURL.split("base64,")[1]);
        var len = bin.length ;

        return dataURL;
    };
})();

