(function() {
    'use strict';

    // --- ฟังก์ชันช่วยเหลือ (Helpers) ---
    async function getRecordIdByCode(codeValue) {
        const params = {
            app: kintone.app.getId(),
            query: `Number = "${codeValue}" limit 1` // ตรวจสอบ Field code: Number ในรูป 1
        };
        const resp = await kintone.api(kintone.api.url('/k/v1/records.json', true), 'GET', params);
        return resp.records.length > 0 ? resp.records[0].$id.value : null;
    }

    async function updateRecord(recordId, billSplittingValue) {
        const params = {
            app: kintone.app.getId(),
            id: recordId,
            record: {
                'Text_5': { value: billSplittingValue } // ตรวจสอบ Field code: Text_5 ในรูป 2
            }
        };
        return kintone.api(kintone.api.url('/k/v1/record.json', true), 'PUT', params);
    }

    // --- ส่วนการจัดการเหตุการณ์ (Events) ---
    kintone.events.on('app.record.index.show', function(event) {
        if (document.getElementById('update_excel_btn')) return;

        const header = kintone.app.getHeaderMenuSpaceElement();
        const container = document.createElement('div');
        container.style.display = 'inline-block';
        container.style.padding = '10px';

        // 1. ปุ่มดาวน์โหลด Master File
        const btnDownload = document.createElement('button');
        btnDownload.innerText = '📥 โหลด Master Excel';
        btnDownload.className = 'kintoneplugin-button-dialog-ok';
        btnDownload.style.backgroundColor = '#3498db';
        btnDownload.style.marginRight = '10px';
        btnDownload.onclick = async () => {
            const workbook = new ExcelJS.Workbook();
            const sheet = workbook.addWorksheet('UpdateSheet');
            // ใส่ Header ให้ไฟล์
            sheet.getRow(1).values = ['Code', 'Bill Splitting (New Value)'];
            sheet.getColumn(1).width = 20;
            sheet.getColumn(2).width = 30;

            const buffer = await workbook.xlsx.writeBuffer();
            const blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
            const link = document.createElement('a');
            link.href = window.URL.createObjectURL(blob);
            link.download = 'Master_Update_BillSplitting.xlsx';
            link.click();
        };

        // 2. ปุ่มอัปโหลดไฟล์
        const fileInput = document.createElement('input');
        fileInput.type = 'file';
        fileInput.style.display = 'none';

        const btnUpload = document.createElement('button');
        btnUpload.innerText = '📤 อัปเดตข้อมูลจาก Excel';
        btnUpload.className = 'kintoneplugin-button-dialog-ok';
        btnUpload.id = 'update_excel_btn';
        btnUpload.onclick = () => fileInput.click();

        // 3. Logic การอ่านไฟล์เมื่อมีการเลือกไฟล์
        fileInput.addEventListener('change', async (e) => {
            const file = e.target.files[0];
            if (!file) return;

            const workbook = new ExcelJS.Workbook();
            const reader = new FileReader();

            reader.onload = async (event) => {
                const buffer = event.target.result;
                await workbook.xlsx.load(buffer);
                const worksheet = workbook.getWorksheet(1);
                
                let successCount = 0;
                let errorCount = 0;

                for (let i = 2; i <= worksheet.rowCount; i++) {
                    const code = worksheet.getRow(i).getCell(1).value; 
                    const newValue = worksheet.getRow(i).getCell(2).value;

                    if (code) {
                        try {
                            const recordId = await getRecordIdByCode(code);
                            if (recordId) {
                                await updateRecord(recordId, String(newValue || ""));
                                successCount++;
                            } else {
                                errorCount++;
                            }
                        } catch (err) {
                            errorCount++;
                        }
                    }
                }
                alert(`อัปเดตเรียบร้อย!\nสำเร็จ: ${successCount}\nไม่พบข้อมูล: ${errorCount}`);
                location.reload();
            };
            reader.readAsArrayBuffer(file);
        });

        container.appendChild(btnDownload);
        container.appendChild(btnUpload);
        container.appendChild(fileInput);
        header.appendChild(container);
    });
})();
